from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console, log_info_to_console
from taf.ul.sc.perf.exceptions import UENotConnected


@log_function_status_to_console(msg="Check if all BTSs are onAir", log_hierarchy=2)
@log_debug_function_info()
def wait_for_all_sites_onair():
    bts_status = {}
    raise_error = False if tc.is_feature_enabled("bts_recovery") else True

    for bts in tc.required_btss():
        bts_status[bts.name] = bts.wait_for_onair(raise_error=raise_error)

    if tc.is_feature_enabled("bts_recovery") and not all(bts_status.values()):
        _recover_selected_bts(bts_status)


def _recover_selected_bts(bts_status):
    for bts in tc.required_btss():
        if not bts_status[bts.name]:
            log_info_to_console(msg="[{}] is not onAir. Try to recover by perform reboot".format(bts.name),
                                log_hierarchy=2)
            bts.bts.reboot()

    for bts in tc.required_btss():
        bts.waiting_for_site_response()
        bts_status[bts.name] = bts.wait_for_onair(raise_error=True)


@log_debug_function_info()
def perform_additional_actions_before_start_scenario():
    perf.tl.ue.synchronize_bts_link(small_cell_enbs=perf.tl.small_cell_enbs)
    perf.tl.ue.perform_additional_actions_before_start_scenario()


def _check_uesim_connection_status(retries=1):
    status = perf.tl.ue.check_if_connected_and_if_not_perform_recovery()
    if not status and retries > 0:
        wait_for_all_sites_onair()
        _check_uesim_connection_status(retries - 1)
    elif not status and retries == 0:
        raise UENotConnected('UEsim did not reach connected status')


@log_debug_function_info()
def verify_if_sample_scenario_can_be_run():
    _check_uesim_connection_status()
